import React from "react";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SearchSuggestionProps = Record<string, any>;

const SearchSuggestion: React.FC<SearchSuggestionProps> = ({
  backgroundColor = "#f0f2f5",
  transparentBackground = false,
  durationInSeconds = 8,
  searchQuery = "How to get a good extraction with Breville?",
  suggestionPreText = "Did you mean",
  suggestionTerm = "Hypergrind Bottomless Portafilter",
  primaryBrandColor = "#4285F4",
}) => {
  useFontLoader(["Roboto", "Open Sans"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Calculations & Animations ---
  
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Content Entrance (replaces phone entrance)
  const contentEnter = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
    delay: 5,
  });

  const contentScale = interpolate(contentEnter, [0, 1], [0.9, 1]);
  const contentOpacity = interpolate(contentEnter, [0, 1], [0, 1]);
  const contentTranslateY = interpolate(contentEnter, [0, 1], [50, 0]);

  // Typing Animation
  const typeStartFrame = 30;
  const typingDuration = searchQuery.length * 3; // 3 frames per char
  const typeProgress = interpolate(
    frame,
    [typeStartFrame, typeStartFrame + typingDuration],
    [0, searchQuery.length],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  
  const currentText = searchQuery.slice(0, Math.round(typeProgress));
  const showCursor = frame > typeStartFrame && frame < typeStartFrame + typingDuration + 20;
  const cursorOpacity = Math.round(frame / 15) % 2 === 0 ? 1 : 0;

  // Suggestion Animation
  const suggestionStartFrame = typeStartFrame + typingDuration + 20;
  const suggestionOpacity = interpolate(
    frame,
    [suggestionStartFrame, suggestionStartFrame + 20],
    [0, 1],
    { extrapolateRight: "clamp" }
  );
  const suggestionY = interpolate(
    frame,
    [suggestionStartFrame, suggestionStartFrame + 20],
    [20, 0],
    { extrapolateRight: "clamp", easing: (t) => t * (2 - t) }
  );

  // --- Styles ---

  const contentWidth = Math.min(width * 0.9, 600);
  const logoColors = ["#4285F4", "#EA4335", "#FBBC05", "#4285F4", "#34A853", "#EA4335"]; // G-o-o-g-l-e

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", justifyContent: "center", alignItems: "center" }}>
      
      {/* Main Content Container (Previously inside Phone) */}
      <div
        style={{
          width: contentWidth,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          opacity: contentOpacity,
          transform: `scale(${contentScale}) translateY(${contentTranslateY}px)`,
          fontFamily: "Roboto, sans-serif",
        }}
      >
          
        {/* Logo */}
        <div style={{ fontSize: contentWidth * 0.15, fontWeight: "bold", marginBottom: 30, letterSpacing: -2 }}>
          <span style={{ color: logoColors[0] }}>G</span>
          <span style={{ color: logoColors[1] }}>o</span>
          <span style={{ color: logoColors[2] }}>o</span>
          <span style={{ color: logoColors[3] }}>g</span>
          <span style={{ color: logoColors[4] }}>l</span>
          <span style={{ color: logoColors[5] }}>e</span>
        </div>

        {/* Search Bar */}
        <div
          style={{
            width: "100%",
            height: 50,
            borderRadius: 25,
            border: "1px solid #dfe1e5",
            backgroundColor: "#ffffff",
            boxShadow: "0 1px 6px rgba(32,33,36,0.28)",
            display: "flex",
            alignItems: "center",
            padding: "0 15px",
            marginBottom: 30,
          }}
        >
          {/* Search Icon SVG */}
          <svg width="20" height="20" viewBox="0 0 24 24" fill="#9aa0a6">
            <path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z" />
          </svg>

          {/* Input Text */}
          <div
            style={{
              flex: 1,
              marginLeft: 12,
              fontSize: 16,
              color: "#202124",
              whiteSpace: "nowrap",
              overflow: "hidden",
              display: "flex",
              alignItems: "center",
            }}
          >
            {currentText}
            {showCursor && (
              <div style={{ width: 2, height: 20, backgroundColor: primaryBrandColor, opacity: cursorOpacity, marginLeft: 2 }} />
            )}
          </div>

          {/* Mic Icon SVG */}
          <svg width="20" height="20" viewBox="0 0 24 24" fill={primaryBrandColor} style={{ marginLeft: 10 }}>
            <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z" />
            <path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z" />
          </svg>
        </div>

        {/* Suggestion Block */}
        <div
          style={{
            width: "100%",
            opacity: suggestionOpacity,
            transform: `translateY(${suggestionY}px)`,
            textAlign: "left",
            paddingLeft: 5,
          }}
        >
          <div style={{ fontSize: 16, color: "#EA4335", marginBottom: 4 }}>
            <span style={{ color: "#333", marginRight: 5 }}>{suggestionPreText}</span>
            <span
              style={{
                fontWeight: "bold",
                color: "#1a0dab",
                fontStyle: "italic",
                cursor: "pointer",
                textDecoration: "underline"
              }}
            >
              {suggestionTerm}
            </span>
            ?
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SearchSuggestion;